/* =====================================================================
   LOADER IMAGES — INLINED AS BASE64 DATA URIs
===================================================================== */
const LOADER_LOGO_DATA_URI = "data:image/png;base64,";
const LOADER_ORBIT_DATA_URI = "data:image/png;base64,";

/* ===================== HEADER SHRINK ON SCROLL ===================== */
(function () {

    const header = document.getElementById('siteHeader');

    if (!header) return;

    function updateHeader() {
        if (window.scrollY > 40) {
            header.classList.add('is-scrolled');
        } else {
            header.classList.remove('is-scrolled');
        }
    }
    window.addEventListener('scroll', updateHeader, {
        passive: true
    });
    updateHeader();

})();


/* ===================== HERO PARALLAX ===================== */
(function () {

    const hero = document.querySelector('.hero');
    const video = document.querySelector('.hero-video');

    if (!hero || !video) return;

    let ticking = false;

    function updateParallax() {

        const scrollY = window.scrollY;

        const heroHeight = hero.offsetHeight;

        if (scrollY <= heroHeight) {

            video.style.transform =
                `translateY(${scrollY * 0.25}px)`;

        }

        ticking = false;

    }

    window.addEventListener('scroll', function () {

        if (!ticking) {

            window.requestAnimationFrame(updateParallax);

            ticking = true;

        }

    }, { passive: true });

})();


/* ===================== LOADING THROBBER ===================== */
(function initLoader() {
  const overlay = document.getElementById('loaderOverlay');
  if (!overlay) return;

  // Swap the page's own loader images (rendered by PHP via base_url()) to
  // the inlined data URIs so they never depend on the network either.
  const orbitImg = overlay.querySelector('.orbit-image');
  const logoImg  = overlay.querySelector('.loader-logo');
  if (orbitImg) orbitImg.src = LOADER_ORBIT_DATA_URI;
  if (logoImg)  logoImg.src  = LOADER_LOGO_DATA_URI;

  function hideLoader() {
    overlay.classList.add('hidden');
    setTimeout(() => {
      if (overlay.parentNode) overlay.remove();
    }, 700);
  }

  if (document.readyState === 'complete') {
    setTimeout(hideLoader, 400);
  } else {
    window.addEventListener('load', hideLoader);
    setTimeout(hideLoader, 5000);
  }
})();


/* ===================== NAV DRAWER DROPDOWNS ===================== */
(function drawerDropdowns() {
    document.querySelectorAll('.sub-toggle').forEach(btn => {
        btn.addEventListener('click', () => {
            const item   = btn.closest('.has-sub');
            const isOpen = item.classList.contains('open');

            // close any other open dropdown first
            document.querySelectorAll('.has-sub.open').forEach(other => {
                other.classList.remove('open');
                other.querySelector('.sub-toggle').setAttribute('aria-expanded', 'false');
            });

            if (!isOpen) {
                item.classList.add('open');
                btn.setAttribute('aria-expanded', 'true');
            }
        });
    });
})();


/* ===================== BURGER / NAV DRAWER ===================== */
(function navDrawer() {
  const burgerBtn = document.getElementById('burgerBtn');
  const navMenu = document.getElementById('navMenu');
  const navOverlay = document.getElementById('navOverlay');

  if (!burgerBtn || !navMenu || !navOverlay) return;

  function openMenu() {
    navMenu.classList.add('open');
    navOverlay.classList.add('visible');
    burgerBtn.setAttribute('aria-expanded', 'true');
  }

  function closeMenu() {
    navMenu.classList.remove('open');
    navOverlay.classList.remove('visible');
    burgerBtn.setAttribute('aria-expanded', 'false');
  }

  function toggleMenu() {
    const isOpen = navMenu.classList.contains('open');
    isOpen ? closeMenu() : openMenu();
  }

  burgerBtn.addEventListener('click', toggleMenu);
  navOverlay.addEventListener('click', closeMenu);

  navMenu.querySelectorAll('a').forEach(link => {
    link.addEventListener('click', closeMenu);
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') closeMenu();
  });
})();


/* ===================== SEARCH ICON / INLINE EXPAND + RESULTS ===================== */
(function searchInline() {
  const wrap = document.getElementById('searchInline');
  const searchBtn = document.getElementById('searchBtn');
  const input = document.getElementById('searchInput');
  const closeBtn = document.getElementById('searchCloseBtn');

  if (!wrap || !searchBtn || !input || !closeBtn) return;

  const lang = () => window.currentLang || localStorage.getItem('siteLang') || 'en';

  // Quick links to site sections (label per language + extra keywords)
  const PAGES = [
    { en: 'Universitas Agriculturae', tl: 'Universitas Agriculturae', kw: 'about university history mission vision', sel: '.about-modal-trigger' },
    { en: 'Admissions', tl: 'Pagpasok', kw: 'admission apply enroll enrollment programs courses pagpasok', sel: '.admissions-modal-trigger' },
    { en: 'Offices', tl: 'Mga Tanggapan', kw: 'office offices registrar tanggapan', sel: 'a[href$="offices"]' },
    { en: 'Careers', tl: 'Karera', kw: 'careers jobs hiring work karera', sel: '.careers-modal-trigger' },
    { en: 'Announcements', tl: 'Mga Anunsyo', kw: 'news announcements anunsyo', sel: 'a[href$="#announcements"]' },
    { en: 'Contact', tl: 'Makipag-ugnayan', kw: 'contact email phone address ugnayan', sel: 'a[href$="#contact"]' }
  ];

  const results = document.createElement('div');
  results.className = 'search-results';
  results.hidden = true;
  wrap.appendChild(results);

  function openSearch() {
    wrap.classList.add('active');
    setTimeout(() => input.focus(), 250);
  }

  function closeSearch() {
    wrap.classList.remove('active');
    input.value = '';
    input.blur();
    results.hidden = true;
    results.innerHTML = '';
  }

  function toggleSearch() {
    wrap.classList.contains('active') ? closeSearch() : openSearch();
  }

  function addGroup(title) {
    const h = document.createElement('div');
    h.className = 'search-group';
    h.textContent = title;
    results.appendChild(h);
  }

  function addItem(label, sub, onClick) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'search-item';
    const t = document.createElement('span');
    t.className = 'search-item-title';
    t.textContent = label;
    btn.appendChild(t);
    if (sub) {
      const s = document.createElement('span');
      s.className = 'search-item-sub';
      s.textContent = sub;
      btn.appendChild(s);
    }
    btn.addEventListener('click', () => {
      closeSearch();
      onClick();
    });
    results.appendChild(btn);
  }

  function snippet(text, idx, len) {
    const start = Math.max(0, idx - 30);
    const end = Math.min(text.length, idx + len + 60);
    return (start > 0 ? '…' : '') + text.slice(start, end).trim() + (end < text.length ? '…' : '');
  }

  function findOnPage(q) {
    const skip = '#siteHeader, #navMenu, .nav-overlay, .about-modal-overlay, .search-results, script, style, noscript';
    const found = [];
    const seen = new Set();

    document.querySelectorAll('h1,h2,h3,h4,h5,p,li,figcaption,td,th,blockquote').forEach(el => {
      if (found.length >= 8) return;
      if (el.closest(skip)) return;
      if (el.offsetParent === null) return; // hidden
      if (el.querySelector('h1,h2,h3,h4,h5,p,li')) return; // use the innermost element only

      const text = el.textContent.replace(/\s+/g, ' ').trim();
      const idx = text.toLowerCase().indexOf(q);
      if (idx === -1 || seen.has(text)) return;

      seen.add(text);
      found.push({ el, text, idx });
    });
    return found;
  }

  function goTo(el) {
    el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    el.classList.add('search-hit');
    setTimeout(() => el.classList.remove('search-hit'), 2500);
  }

  function render() {
    const q = input.value.trim().toLowerCase();
    results.innerHTML = '';

    if (q.length < 2) {
      results.hidden = true;
      return;
    }

    const L = lang();

    const pageMatches = PAGES.filter(p =>
      (p.en + ' ' + p.tl + ' ' + p.kw).toLowerCase().includes(q)
    );
    if (pageMatches.length) {
      addGroup(L === 'tl' ? 'Mga Pahina' : 'Pages');
      pageMatches.forEach(p => {
        addItem(p[L], null, () => {
          const link = document.querySelector(p.sel);
          if (link) link.click();
        });
      });
    }

    const textMatches = findOnPage(q);
    if (textMatches.length) {
      addGroup(L === 'tl' ? 'Sa pahinang ito' : 'On this page');
      textMatches.forEach(m => {
        addItem(snippet(m.text, m.idx, q.length), null, () => goTo(m.el));
      });
    }

    if (!pageMatches.length && !textMatches.length) {
      const empty = document.createElement('div');
      empty.className = 'search-empty';
      empty.textContent = L === 'tl' ? 'Walang nahanap.' : 'No results found.';
      results.appendChild(empty);
    }

    results.hidden = false;
  }

  searchBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    toggleSearch();
  });

  closeBtn.addEventListener('click', closeSearch);
  input.addEventListener('input', render);

  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      const first = results.querySelector('.search-item');
      if (first) first.click();
    }
  });

  document.addEventListener('click', (e) => {
    if (!wrap.classList.contains('active')) return;
    if (wrap.contains(e.target)) return;
    closeSearch();
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && wrap.classList.contains('active')) closeSearch();
  });

  // Close on scroll only when nothing is typed (so result clicks/scrolls don't fight it)
  window.addEventListener('scroll', () => {
    if (wrap.classList.contains('active') && !input.value.trim()) {
      closeSearch();
    }
  }, { passive: true });
})();


/* ===================== LANGUAGE TOGGLE ===================== */
(function languageToggle() {
  const STORAGE_KEY = 'siteLang';
  const langButtons = document.querySelectorAll('.lang-btn');
  if (!langButtons.length) return;

  let currentLang = localStorage.getItem(STORAGE_KEY) || 'en';

  function translate(root, lang) {
    if (root.nodeType !== 1) return;

    const nodes = root.matches('[data-en][data-tl]') ? [root] : [];
    root.querySelectorAll('[data-en][data-tl]').forEach(el => nodes.push(el));

    nodes.forEach(el => {
      const text = el.getAttribute('data-' + lang);
      if (text !== null) el.textContent = text;
    });

    // Placeholders: data-en-placeholder / data-tl-placeholder
    const phNodes = root.matches('[data-en-placeholder]') ? [root] : [];
    root.querySelectorAll('[data-en-placeholder]').forEach(el => phNodes.push(el));

    phNodes.forEach(el => {
      const ph = el.getAttribute('data-' + lang + '-placeholder');
      if (ph !== null) el.setAttribute('placeholder', ph);
    });
  }

  function setLang(lang) {
    currentLang = lang;
    localStorage.setItem(STORAGE_KEY, lang);
    document.documentElement.lang = lang === 'tl' ? 'fil' : 'en';

    langButtons.forEach(b => b.classList.toggle('active', b.dataset.lang === lang));
    translate(document.body, lang);
    window.currentLang = lang;
  }

  langButtons.forEach(btn => {
    btn.addEventListener('click', () => setLang(btn.dataset.lang));
  });

  // Translate content injected later (About / Admissions / Careers modals)
  new MutationObserver(mutations => {
    if (currentLang === 'en') return;
    mutations.forEach(m => m.addedNodes.forEach(n => translate(n, currentLang)));
  }).observe(document.body, { childList: true, subtree: true });

  setLang(currentLang);
})();


/* ===================== HEADER DROPDOWN (Admissions) ===================== */
(function headerDropdown() {
  const dropdowns = document.querySelectorAll('.nav-dropdown');
  if (!dropdowns.length) return;

  function setOpen(dd, open) {
    dd.classList.toggle('open', open);
    const toggle = dd.querySelector('.nav-dropdown-toggle');
    if (toggle) toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
  }

  dropdowns.forEach(dd => {
    const toggle = dd.querySelector('.nav-dropdown-toggle');
    if (!toggle) return;

    toggle.addEventListener('click', (e) => {
      e.preventDefault();
      setOpen(dd, !dd.classList.contains('open'));
    });

    dd.addEventListener('mouseleave', () => setOpen(dd, false));
  });

  document.addEventListener('click', (e) => {
    dropdowns.forEach(dd => {
      if (!dd.contains(e.target)) setOpen(dd, false);
    });
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') dropdowns.forEach(dd => setOpen(dd, false));
  });
})();


/* ===================== CAMPUS HIGHLIGHTS SLIDER ===================== */
(function campusSlider() {
  const track = document.getElementById('campusSliderTrack');
  const prevBtn = document.getElementById('campusPrevBtn');
  const nextBtn = document.getElementById('campusNextBtn');

  if (!track || !prevBtn || !nextBtn) return;

  const viewport = track.parentElement;
  const slides = Array.from(track.children);
  if (!slides.length) return;

  let activeIndex = Math.min(2, slides.length - 1);

  function update() {
    slides.forEach((slide, i) => {
      slide.classList.toggle('is-active', i === activeIndex);
    });

    const activeSlide = slides[activeIndex];
    const viewportWidth = viewport.offsetWidth;
    const slideCenter = activeSlide.offsetLeft + activeSlide.offsetWidth / 2;
    const offset = viewportWidth / 2 - slideCenter;

    track.style.transform = `translateX(${offset}px)`;

    prevBtn.disabled = activeIndex === 0;
    nextBtn.disabled = activeIndex === slides.length - 1;
  }

  prevBtn.addEventListener('click', () => {
    if (activeIndex > 0) {
      activeIndex--;
      update();
    }
  });

  nextBtn.addEventListener('click', () => {
    if (activeIndex < slides.length - 1) {
      activeIndex++;
      update();
    }
  });

  window.addEventListener('resize', update, { passive: true });
  window.addEventListener('load', update);

  update();
})();


// ===================== FOOTER SHARE ROW =====================
(function () {
  var row = document.querySelector('[data-share-row]');
  if (!row) return;

  var copiedNote = document.querySelector('[data-share-copied]');

  function openPopup(url) {
    var w = 600, h = 500;
    var left = (window.screen.width - w) / 2;
    var top = (window.screen.height - h) / 2;
    window.open(
      url,
      'share',
      'width=' + w + ',height=' + h + ',left=' + left + ',top=' + top + ',noopener,noreferrer'
    );
  }

  function shareLinks(pageUrl, pageTitle) {
    var u = encodeURIComponent(pageUrl);
    var t = encodeURIComponent(pageTitle);
    return {
      facebook: 'https://www.facebook.com/sharer/sharer.php?u=' + u,
      x: 'https://twitter.com/intent/tweet?url=' + u + '&text=' + t,
      linkedin: 'https://www.linkedin.com/sharing/share-offsite/?url=' + u,
      whatsapp: 'https://api.whatsapp.com/send?text=' + t + '%20' + u,
      telegram: 'https://t.me/share/url?url=' + u + '&text=' + t,
      email: 'mailto:?subject=' + t + '&body=' + u
    };
  }

  row.addEventListener('click', function (e) {
    var btn = e.target.closest('[data-share]');
    if (!btn) return;

    var platform = btn.getAttribute('data-share');
    var pageUrl = window.location.href;
    var pageTitle = document.title;

    if (platform === 'copy') {
      navigator.clipboard.writeText(pageUrl).then(function () {
        if (!copiedNote) return;
        copiedNote.hidden = false;
        copiedNote.classList.add('is-visible');
        setTimeout(function () {
          copiedNote.classList.remove('is-visible');
          setTimeout(function () { copiedNote.hidden = true; }, 200);
        }, 1800);
      });
      return;
    }

    var links = shareLinks(pageUrl, pageTitle);
    var target = links[platform];
    if (!target) return;

    if (platform === 'email') {
      window.location.href = target;
    } else {
      openPopup(target);
    }
  });
})();


/* ===================== HERO RANK SWITCHER ===================== */
(function heroAutoSlider() {

    const hero = document.querySelector('.hero');
    const slides = [...document.querySelectorAll('.hero-slide')];

    if (!hero || !slides.length) return;

    let current = 0;
    let timer = null;

    const duration = 4000;

    function showSlide(index) {

        current = index;

        slides.forEach((slide, i) => {
            slide.classList.toggle(
                'is-active',
                i === current
            );
        });
    }

    function nextSlide() {

        const next = (current + 1) % slides.length;

        showSlide(next);
    }

    function startSlider() {

        if (
            window.matchMedia(
                '(prefers-reduced-motion: reduce)'
            ).matches
        ) {
            return;
        }

        stopSlider();

        timer = setInterval(
            nextSlide,
            duration
        );
    }

    function stopSlider() {

        if (timer) {
            clearInterval(timer);
            timer = null;
        }
    }

    showSlide(0);
    startSlider();

})();


/* ===================== ADMISSIONS: SUB-MODALS (applicant type, majors, etc.) ===================== */
function wireAdmSubModals(root, scopedModals) {
  function openAdmModal(modal) {
    modal.classList.add('is-open');
    document.body.style.overflow = 'hidden';
  }

  function closeAdmModal(modal) {
    modal.classList.remove('is-open');
    if (!document.querySelector('.adm-modal-overlay.is-open') &&
        !document.querySelector('.about-modal-overlay.is-open')) {
      document.body.style.overflow = '';
    }
  }

  var modals = scopedModals || root.querySelectorAll('.adm-modal-overlay');

  root.querySelectorAll('[data-modal]').forEach(function (trigger) {
    trigger.addEventListener('click', function (e) {
      e.preventDefault();
      var id = trigger.getAttribute('data-modal');
      var modal = Array.prototype.find.call(modals, function (m) { return m.id === id; })
        || document.getElementById(id);
      if (modal) openAdmModal(modal);
    });
  });

  modals.forEach(function (modal) {
    modal.querySelectorAll('[data-modal-close]').forEach(function (closer) {
      closer.addEventListener('click', function () { closeAdmModal(modal); });
    });
    modal.addEventListener('click', function (e) {
      if (e.target === modal) closeAdmModal(modal);
    });
  });
}

document.addEventListener('keydown', function (e) {
  if (e.key !== 'Escape') return;
  var anyClosed = false;
  document.querySelectorAll('.adm-modal-overlay.is-open').forEach(function (modal) {
    modal.classList.remove('is-open');
    anyClosed = true;
  });
  if (anyClosed && !document.querySelector('.about-modal-overlay.is-open')) {
    document.body.style.overflow = '';
  }
});

document.addEventListener('DOMContentLoaded', function () {
  wireAdmSubModals(document);
});


/* ===================== ENROLLMENT SCHEDULE CALENDAR ===================== */
function wireEnrollmentCalendar(root) {
  var days = root.querySelectorAll('.enr-day.is-enroll');
  if (!days.length) return;

  days.forEach(function (btn) {
    btn.addEventListener('click', function () {
      root.querySelectorAll('.enr-day.is-active, .enr-panel.is-active')
        .forEach(function (el) { el.classList.remove('is-active'); });

      btn.classList.add('is-active');

      var panel = root.querySelector('#enr-panel-' + btn.dataset.day);
      if (panel) panel.classList.add('is-active');
    });
  });
}

document.addEventListener('DOMContentLoaded', function () {
  wireEnrollmentCalendar(document);
});


/* ===================== PROGRAMS BY COLLEGE — ACCORDION ===================== */
function wireCollegeAccordion(root, opts) {
  opts = opts || {};
  var toggles = root.querySelectorAll('.college-toggle');
  if (!toggles.length) return;

  var singleOpen = false;

  function setOpen(block, open) {
    var btn = block.querySelector('.college-toggle');
    block.classList.toggle('is-open', open);
    if (btn) btn.setAttribute('aria-expanded', open ? 'true' : 'false');
  }

  toggles.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var block = btn.closest('.college-block');
      var open  = !block.classList.contains('is-open');

      if (singleOpen && open) {
        root.querySelectorAll('.college-block.is-open').forEach(function (other) {
          if (other !== block) setOpen(other, false);
        });
      }
      setOpen(block, open);
    });
  });

  if (opts.openFromHash) {
    var id = window.location.hash.slice(1);
    if (id) {
      var block = root.querySelector('#' + CSS.escape(id));
      if (block && block.classList.contains('college-block')) {
        setOpen(block, true);
        block.scrollIntoView({ block: 'start' });
      }
    }
    window.addEventListener('hashchange', function () {
      var hid = window.location.hash.slice(1);
      var hblock = hid && root.querySelector('#' + CSS.escape(hid));
      if (hblock && hblock.classList.contains('college-block')) {
        setOpen(hblock, true);
        hblock.scrollIntoView({ block: 'start' });
      }
    });
  }
}

document.addEventListener('DOMContentLoaded', function () {
  wireCollegeAccordion(document, { openFromHash: true });
});


/* ===================== QUICK-JUMP: SCROLL WITHIN CONTAINER (used inside modals) ===================== */
function wireQuickJumpWithin(root, scrollContainer) {
  root.querySelectorAll('.quick-jump-btn[href^="#"]').forEach(function (link) {
    link.addEventListener('click', function (e) {
      var id = link.getAttribute('href').slice(1);
      var target = root.querySelector('#' + CSS.escape(id));
      if (!target) return;
      e.preventDefault();
      target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  });
}


(function () {
  const rows = document.querySelectorAll('.hours-row');
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long' });
  rows.forEach(row => {
    if (row.querySelector('.hours-day').textContent.trim() === today) {
      row.classList.add('is-today');
    }
  });
})();

/* ===================== QUICK-JUMP DROPDOWN (mobile panel switcher) =====================*/
function wireQuickJumpSelect(root) {
  var select = root.querySelector('.quick-jump-select');
  if (!select) return;

  var navLinks = root.querySelectorAll('.quick-jump-btn[data-panel]');
  var panels   = root.querySelectorAll('.admissions-panel[data-panel]');
  if (!navLinks.length || !panels.length) return;

  if (select.dataset.wired === 'true') return;
  select.dataset.wired = 'true';

  function showPanel(name) {
    panels.forEach(function (p) {
      p.hidden = p.getAttribute('data-panel') !== name;
    });

    navLinks.forEach(function (a) {
      var isActive = a.getAttribute('data-panel') === name;
      a.classList.toggle('active', isActive);
      if (isActive) {
        a.setAttribute('aria-current', 'page');
      } else {
        a.removeAttribute('aria-current');
      }
    });

    if (window.history && history.replaceState) {
      history.replaceState(null, '', '#' + name);
    }

    var scroller = document.getElementById('admissionsModalBody')
      || document.scrollingElement
      || document.documentElement;
    scroller.scrollTo({ top: 0, behavior: 'auto' });

    var section = root.querySelector('#' + name);
    if (section) {
      section.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  }

  select.addEventListener('change', function () {
    showPanel(select.value);
  });

  navLinks.forEach(function (btn) {
    btn.addEventListener('click', function () {
      select.value = btn.dataset.panel;
    });
  });
}

document.addEventListener('DOMContentLoaded', function () {
  var root = document.querySelector('.admissions-page');
  if (root) wireQuickJumpSelect(root);
});


/* ===================== ABOUT — SIDEBAR PANEL SWITCHING ===================== */
function wireAboutLayout(layout) {
  const links    = layout.querySelectorAll('.side-nav a[data-panel]');
  const panels   = layout.querySelectorAll('.about-panel');
  const hashSync = layout.dataset.hashSync === 'true';
  const inModal  = !!layout.closest('#aboutModalBody');
  const select   = layout.querySelector('.about-nav-select');

  const modalTitleEl = document.getElementById('aboutModalPanelTitle');

  if (!links.length || !panels.length) return;

  // Build the mobile dropdown's options from the same links already in the
  // DOM, so the two never fall out of sync.
  if (select && select.dataset.built !== 'true') {
    select.dataset.built = 'true';
    links.forEach(function (link) {
      var opt = document.createElement('option');
      opt.value = link.dataset.panel;
      opt.textContent = link.textContent.trim();
      select.appendChild(opt);
    });
  }

  function show(id) {
    let found = false;
    let activePanel = null;

    panels.forEach(panel => {
      const match = panel.dataset.panel === id;
      panel.hidden = !match;
      if (match) {
        found = true;
        activePanel = panel;
      }
    });

    if (!found) {
      id = panels[0].dataset.panel;
      panels[0].hidden = false;
      activePanel = panels[0];
    }

    links.forEach(link => {
      const on = link.dataset.panel === id;
      link.classList.toggle('active', on);
      if (on) link.setAttribute('aria-current', 'page');
      else link.removeAttribute('aria-current');
    });

    if (select) select.value = id;

    if (inModal) {
      localStorage.setItem('aboutModalPanel', id);
    }

    if (modalTitleEl && layout.closest('#aboutModalBody')) {
      const heading = activePanel.querySelector('h2');
      modalTitleEl.textContent = heading ? heading.textContent : '';
    }
  }

  links.forEach(link => {
    link.addEventListener('click', e => {
      e.preventDefault();
      const id = link.dataset.panel;

      if (hashSync) {
        history.replaceState(null, '', '#' + id);
      }

      show(id);

      if (window.innerWidth <= 900) {
        layout.querySelector('.about-content').scrollIntoView({ behavior: 'smooth' });
      }
    });
  });

  if (select) {
    select.addEventListener('change', function () {
      const id = select.value;

      if (hashSync) {
        history.replaceState(null, '', '#' + id);
      }

      show(id);
      layout.querySelector('.about-content').scrollIntoView({ behavior: 'smooth' });
    });
  }

  const initialId = hashSync
    ? (location.hash.slice(1) || panels[0].dataset.panel)
    : (inModal ? (localStorage.getItem('aboutModalPanel') || panels[0].dataset.panel)
               : panels[0].dataset.panel);

  show(initialId);
}

document.querySelectorAll('.about-layout').forEach(wireAboutLayout);

/* =========================================================
   ADMISSIONS — PANEL SWITCHER
========================================================= */

function admissionsPanels(root) {
  root = root || document.querySelector('.admissions-page');
  if (!root) return;

  if (root.dataset.panelsBound === 'true') {
    return;
  }

  var navLinks = root.querySelectorAll('.quick-jump-btn[data-panel]');
  var panels   = root.querySelectorAll('.admissions-panel[data-panel]');

  if (!navLinks.length || !panels.length) return;

  root.dataset.panelsBound = 'true';

  function showPanel(name, updateHash) {
    panels.forEach(function (p) {
      p.hidden = p.getAttribute('data-panel') !== name;
    });
    navLinks.forEach(function (a) {
      var isActive = a.getAttribute('data-panel') === name;
      a.classList.toggle('active', isActive);
      if (isActive) {
        a.setAttribute('aria-current', 'page');
      } else {
        a.removeAttribute('aria-current');
      }
    });
    if (updateHash && window.history && history.replaceState) {
      history.replaceState(null, '', '#' + name);
    }

    var scroller = document.getElementById('admissionsModalBody') || document.scrollingElement || document.documentElement;
    scroller.scrollTo({ top: 0, behavior: 'auto' });
  }

  navLinks.forEach(function (a) {
    a.addEventListener('click', function (e) {
      e.preventDefault();
      showPanel(a.getAttribute('data-panel'), true);
    });
  });

  var initial = (location.hash || '').replace('#', '');
  var hasPanel = Array.prototype.some.call(panels, function (p) {
    return p.getAttribute('data-panel') === initial;
  });
  if (initial && hasPanel) {
    showPanel(initial, false);
  }
}

(function () {
  document.addEventListener('DOMContentLoaded', function () {
    admissionsPanels();
  });

  var observer = new MutationObserver(function () {
    var root = document.querySelector('.admissions-page');
    if (root && root.dataset.panelsBound !== 'true') {
      admissionsPanels(root);
    }
  });

  observer.observe(document.documentElement, { childList: true, subtree: true });
})();

/* ===================== GENERIC "PAGE IN A MODAL" SYSTEM ===================== */
function initPageModal(config) {
  var triggers = document.querySelectorAll(config.triggerSelector);
  var overlay  = document.getElementById(config.overlayId);
  if (!triggers.length || !overlay) return;

  var closeBtn = overlay.querySelector('.about-modal-close');
  var body     = overlay.querySelector('.about-modal-body');

  var pageUrl     = overlay.dataset.aboutUrl;
  var storageKey  = 'pageModalOpen:' + config.overlayId;
  var loaded      = false;
  var lastFocused = null;

  function loadContent() {
    overlay.classList.add('is-loading');

    // Loader images are inlined as base64 data URIs (see top of this file)
    // so this markup needs zero network requests to paint immediately —
    // no more racing the hero video / fonts / CSS for a connection slot
    // on a fresh page load.
    body.innerHTML =
      '<div class="modal-loader" role="status" aria-live="polite">' +
        '<div class="loader-ring">' +
          '<div class="orbit-wrap">' +
            '<img src="' + LOADER_ORBIT_DATA_URI + '" class="orbit-image" alt="">' +
          '</div>' +
          '<img src="' + LOADER_LOGO_DATA_URI + '" alt="Loading" class="loader-logo">' +
        '</div>' +
        '<span class="sr-only">Loading&hellip;</span>' +
      '</div>';

    Promise.all([
      fetch(pageUrl).then(function (res) {
        if (!res.ok) throw new Error('Request failed: ' + res.status);
        return res.text();
      })
    ])
      .then(function (results) {
        var html = results[0];
        var doc = new DOMParser().parseFromString(html, 'text/html');

        if (!doc.querySelector('base')) {
          var base = doc.createElement('base');
          base.href = pageUrl;
          doc.head.insertBefore(base, doc.head.firstChild);
        }

        var content = doc.querySelector(config.contentSelector);

        if (!content) throw new Error('No ' + config.contentSelector + ' in the fetched page');

        if (config.prepareContent) config.prepareContent(content);

        overlay.classList.remove('is-loading');
        body.innerHTML = '';
        body.appendChild(content);

        if (config.onLoaded) config.onLoaded(content, overlay, body);

        loaded = true;
      })
      .catch(function () {
        overlay.classList.remove('is-loading');
        body.innerHTML =
          '<p class="about-modal-status about-modal-status--error">' +
          "Couldn't load this content right now. " +
          '<a href="' + pageUrl + '">' + (config.fallbackLabel || 'Open the page instead') + '</a>.</p>';
      });
  }

  function openModal(e, isRestore) {
    if (e && e.preventDefault) e.preventDefault();
    lastFocused = document.activeElement;

    // Fresh open (click) -> start from the very first part.
    // Restore (page refresh) -> keep whatever state is saved.
    if (!isRestore) {
      if (config.resetState) config.resetState();
      body.scrollTop = 0;
    }

    overlay.classList.add('is-open');
    document.body.style.overflow = 'hidden';
    if (closeBtn) closeBtn.focus();

    localStorage.setItem(storageKey, 'true');

    if (!loaded) loadContent();
  }

  function closeModal() {
    overlay.classList.remove('is-open');

    document.querySelectorAll('.adm-modal-overlay').forEach(function (m) {
      if (m.dataset.reparentedFor === config.overlayId) {
        m.remove();
      } else {
        m.classList.remove('is-open');
      }
    });

    if (!document.querySelector('.about-modal-overlay.is-open')) {
      document.body.style.overflow = '';
    }

    if (lastFocused) lastFocused.focus();

    localStorage.removeItem(storageKey);
    if (config.resetState) config.resetState();   // closing clears saved position
    if (config.onClose) config.onClose();

    loaded = false;
  }

  triggers.forEach(function (trigger) {
    trigger.addEventListener('click', function (e) { openModal(e, false); });
  });

  if (closeBtn) closeBtn.addEventListener('click', closeModal);

  overlay.addEventListener('click', function (e) {
    if (e.target === overlay) closeModal();
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && overlay.classList.contains('is-open')) closeModal();
  });

  if (localStorage.getItem(storageKey) === 'true') {
    openModal(null, true);   // refresh: restore, don't reset
  }
}

document.querySelectorAll('.sf-tabs').forEach(function (tabBar) {
  var tabs = tabBar.querySelectorAll('.sf-tab');
  var scope = tabBar.closest('.about-panel');

  tabs.forEach(function (tab) {
    tab.addEventListener('click', function () {
      var target = tab.getAttribute('data-sf-tab');

      tabs.forEach(function (t) {
        var isActive = t === tab;
        t.classList.toggle('active', isActive);
        t.setAttribute('aria-selected', isActive ? 'true' : 'false');
        t.tabIndex = isActive ? 0 : -1;
      });

      scope.querySelectorAll('.sf-panel').forEach(function (panel) {
        panel.hidden = panel.getAttribute('data-sf-panel') !== target;
      });
    });
  });
});

function wireSfTabs(root) {
  root.querySelectorAll('.sf-tabs').forEach(function (tabBar) {
    var tabs = tabBar.querySelectorAll('.sf-tab');
    var scope = tabBar.closest('.about-panel');

    tabs.forEach(function (tab) {
      tab.addEventListener('click', function () {
        var target = tab.getAttribute('data-sf-tab');

        tabs.forEach(function (t) {
          var isActive = t === tab;
          t.classList.toggle('active', isActive);
          t.setAttribute('aria-selected', isActive ? 'true' : 'false');
          t.tabIndex = isActive ? 0 : -1;
        });

        scope.querySelectorAll('.sf-panel').forEach(function (panel) {
          panel.hidden = panel.getAttribute('data-sf-panel') !== target;
        });
      });
    });
  });
}

document.querySelectorAll('.about-layout').forEach(function (layout) {
  wireSfTabs(layout);
});


